Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
gpio: cdev: Avoid NULL dereference in linehandle_create()

In linehandle_create(), there is a statement like this:
  retain_and_null_ptr(lh);

Soon after, there is a debug printout that dereferences "lh", which
will crash things.

Avoid the crash by using handlereq.lines, which is the same value.

Fixes: da7e394bf58f ("gpio: convert linehandle_create() to FD_PREPARE()")
Signed-off-by: Douglas Anderson <dianders@chromium.org>
Link: https://patch.msgid.link/20260215120555.v2.1.I77c3eb563271c21870379eefd16ebbc4e09635bb@changeid
Signed-off-by: Bartosz Golaszewski <bartosz.golaszewski@oss.qualcomm.com>

Here is the root cause:
After calling retain_and_null_ptr(lh) in linehandle_create(), the pointer lh is set to NULL. The subsequent dev_dbg() then dereferences lh->num_descs, leading to a NULL pointer dereference and kernel crash.

Here is the patch:

 static int linehandle_create(struct gpio_device *gdev, void __user *ip)
 {
 	struct gpiohandle_request handlereq;
 	struct linehandle_state *lh __free(linehandle_free) = NULL;
 	int i, ret;
 	u32 lflags;

 	if (copy_from_user(&handlereq, ip, sizeof(handlereq)))
 		return -EFAULT;
 	if ((handlereq.lines == 0) || (handlereq.lines > GPIOHANDLES_MAX))
 		return -EINVAL;

 	lflags = handlereq.flags;

 	ret = linehandle_validate_flags(lflags);
 	if (ret)
 		return ret;

 	lh = kzalloc(sizeof(*lh), GFP_KERNEL);
 	if (!lh)
 		return -ENOMEM;
 	lh->gdev = gpio_device_get(gdev);

 	if (handlereq.consumer_label[0] != '\0') {
 		/* label is only initialized if consumer_label is set */
 		lh->label = kstrndup(handlereq.consumer_label,
 				     sizeof(handlereq.consumer_label) - 1,
 				     GFP_KERNEL);
 		if (!lh->label)
 			return -ENOMEM;
 	}

 	lh->num_descs = handlereq.lines;

 	/* Request each GPIO */
 	for (i = 0; i < handlereq.lines; i++) {
 		u32 offset = handlereq.lineoffsets[i];
 		struct gpio_desc *desc = gpio_device_get_desc(gdev, offset);

 		if (IS_ERR(desc))
 			return PTR_ERR(desc);

 		ret = gpiod_request_user(desc, lh->label);
 		if (ret)
 			return ret;
 		lh->descs[i] = desc;
 		linehandle_flags_to_desc_flags(handlereq.flags, &desc->flags);

 		ret = gpiod_set_transitory(desc, false);
 		if (ret < 0)
 			return ret;

 		/*
 		 * Lines have to be requested explicitly for input
 		 * or output, else the line will be treated "as is".
 		 */
 		if (lflags & GPIOHANDLE_REQUEST_OUTPUT) {
 			int val = !!handlereq.default_values[i];

 			ret = gpiod_direction_output_nonotify(desc, val);
 			if (ret)
 				return ret;
 		} else if (lflags & GPIOHANDLE_REQUEST_INPUT) {
 			ret = gpiod_direction_input_nonotify(desc);
 			if (ret)
 				return ret;
 		}

 		gpiod_line_state_notify(desc, GPIO_V2_LINE_CHANGED_REQUESTED);

 		dev_dbg(&gdev->dev, "registered chardev handle for line %d\n",
 			offset);
 	}

 	FD_PREPARE(fdf, O_RDONLY | O_CLOEXEC,
 		   anon_inode_getfile("gpio-linehandle", &linehandle_fileops,
 				      lh, O_RDONLY | O_CLOEXEC));
 	if (fdf.err)
 		return fdf.err;
 	retain_and_null_ptr(lh);

 	handlereq.fd = fd_prepare_fd(fdf);
 	if (copy_to_user(ip, &handlereq, sizeof(handlereq)))
 		return -EFAULT;

 	fd_publish(fdf);

 	dev_dbg(&gdev->dev, "registered chardev handle for %d lines\n",
-		lh->num_descs);
+		handlereq.lines);

 	return 0;
 }
 #endif /* CONFIG_GPIO_CDEV_V1 */


